package mutationscope

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	yaml "go.yaml.in/yaml/v3"
)

// ConfigDir is where generated gremlins configs live, relative to backend/.
const ConfigDir = ".gremlins"

// header is prepended to every generated config so a reader lands on the
// regeneration command instead of hand-editing a derived file.
const header = "" +
	"# Generated by `cd backend && go run ./cmd/genmutationscope` (issue #915).\n" +
	"# Do not hand-edit: TestGeneratedConfigsAreCurrent fails until this file\n" +
	"# matches internal/mutationscope.Scopes again.\n"

type unleashConfig struct {
	Unleash struct {
		ExcludeFiles []string `yaml:"exclude-files"`
		Threshold    struct {
			Efficacy       float64 `yaml:"efficacy"`
			MutantCoverage float64 `yaml:"mutant-coverage"`
		} `yaml:"threshold"`
	} `yaml:"unleash"`
}

// ConfigFileName is the generated config's path for s, relative to backend/.
func ConfigFileName(s Scope) string {
	return filepath.Join(ConfigDir, s.Name+".yaml")
}

// Generate computes the generated config content for every Scope, keyed by
// ConfigFileName. backendDir is the absolute path to the backend/ module
// root, used to list each PackageDir's actual files.
func Generate(backendDir string) (map[string]string, error) {
	out := make(map[string]string, len(Scopes))
	for _, s := range Scopes {
		content, err := generateOne(backendDir, s)
		if err != nil {
			return nil, fmt.Errorf("scope %q: %w", s.Name, err)
		}
		out[ConfigFileName(s)] = content
	}
	return out, nil
}

func generateOne(backendDir string, s Scope) (string, error) {
	var cfg unleashConfig
	cfg.Unleash.Threshold.Efficacy = s.Efficacy
	cfg.Unleash.Threshold.MutantCoverage = s.MutantCoverage
	if len(s.TargetFiles) > 0 {
		excluded, err := excludedFiles(backendDir, s)
		if err != nil {
			return "", err
		}
		for _, f := range excluded {
			cfg.Unleash.ExcludeFiles = append(cfg.Unleash.ExcludeFiles, "^"+regexp.QuoteMeta(f)+"$")
		}
	}

	body, err := yaml.Marshal(&cfg)
	if err != nil { // # pragma: no cover — Marshal of this struct shape can never fail
		return "", err
	}
	return header + string(body), nil
}

// excludedFiles lists every non-test *.go file directly in
// backendDir/s.PackageDir that is not named in s.TargetFiles, sorted.
func excludedFiles(backendDir string, s Scope) ([]string, error) {
	want := make(map[string]bool, len(s.TargetFiles))
	for _, f := range s.TargetFiles {
		want[f] = true
	}

	entries, err := os.ReadDir(filepath.Join(backendDir, s.PackageDir))
	if err != nil {
		return nil, err
	}

	var excluded []string
	seen := make(map[string]bool, len(s.TargetFiles))
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || filepath.Ext(name) != ".go" || strings.HasSuffix(name, "_test.go") {
			continue
		}
		if want[name] {
			seen[name] = true
			continue
		}
		excluded = append(excluded, name)
	}
	for _, f := range s.TargetFiles {
		if !seen[f] {
			return nil, fmt.Errorf("target file %q not found in %s", f, s.PackageDir)
		}
	}
	sort.Strings(excluded)
	return excluded, nil
}

// Write regenerates every scope's config under backendDir/ConfigDir.
func Write(backendDir string) error {
	files, err := Generate(backendDir)
	if err != nil {
		return err
	}
	dir := filepath.Join(backendDir, ConfigDir)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return err
	}
	for rel, content := range files {
		path := filepath.Join(backendDir, rel)
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			return err
		}
	}
	return nil
}
